#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "varh".parse::<ElectricReactiveEnergyUnit>(),
        Ok(ElectricReactiveEnergyUnit::VoltampereReactiveHour)
    );
    assert_eq!(
        format!("2.5 {}", "varh").parse::<ElectricReactiveEnergy>(),
        Ok(ElectricReactiveEnergy::new(
            2.5,
            ElectricReactiveEnergyUnit::VoltampereReactiveHour
        ))
    );
    assert_eq!(
        "kvarh".parse::<ElectricReactiveEnergyUnit>(),
        Ok(ElectricReactiveEnergyUnit::KilovoltampereReactiveHour)
    );
    assert_eq!(
        format!("2.5 {}", "kvarh").parse::<ElectricReactiveEnergy>(),
        Ok(ElectricReactiveEnergy::new(
            2.5,
            ElectricReactiveEnergyUnit::KilovoltampereReactiveHour
        ))
    );
    assert_eq!(
        "Mvarh".parse::<ElectricReactiveEnergyUnit>(),
        Ok(ElectricReactiveEnergyUnit::MegavoltampereReactiveHour)
    );
    assert_eq!(
        format!("2.5 {}", "Mvarh").parse::<ElectricReactiveEnergy>(),
        Ok(ElectricReactiveEnergy::new(
            2.5,
            ElectricReactiveEnergyUnit::MegavoltampereReactiveHour
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricReactiveEnergy>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricReactiveEnergy::from_base(6.0);
    let b = ElectricReactiveEnergy::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

